/**
 * Renders a LibKa document as an editable, tagged Word file (DOCX).
 *
 * Real Word structure throughout: the Title style and Heading 1–3 (## to ####), numbered and bulleted lists,
 * tables with a repeating header row and alternative text, footnotes, internal links to bookmarks, pictures with
 * alternative text, and the document language on every run and in the properties. Styles come from the tokens
 * (theme.ts, generated by generate.py). Blocks Word has no structure for get a documented fallback: callouts,
 * cards and other panels are bordered, shaded paragraphs (never layout tables), tabs and accordions are opened,
 * diagrams, charts and UI specimens are pictures the caller draws (with the chart's data as a table and every
 * diagram's source in an appendix), a video is a link with its transcript.
 *
 * Pure and browser-safe: pictures come from the caller (`picture` for figures, `drawing` for diagrams, charts and
 * specimens). The same source gives the same bytes (see package.ts).
 */
import {
  AlignmentType, Bookmark, BorderStyle, Document, ExternalHyperlink, Footer, FootnoteReferenceRun, HeadingLevel, ImageRun,
  InternalHyperlink, LevelFormat, Packer, PageNumber, Paragraph, ShadingType, Table, TableCell, TableRow, TextRun, WidthType,
  type IBordersOptions, type ILevelsOptions, type IParagraphOptions, type ParagraphChild,
} from 'docx';
import type { PhrasingContent } from 'mdast';
import { isDeprecated, kbdKeys, plainText, type Block, type Citation, type Inline, type LibkaDocument } from '@libka/model';
import {
  chartText, citationParts, czechText, describeUi, docInfo, fill, LABELS, langOf, NOTES_ID, orderedReferences, referenceParts,
  REFERENCES_ID, safeHref, type DocInfo, type Labels, type Lang,
} from '@libka/render';
import { normalize, type DocxPicture } from './package.ts';
import { THEME } from './theme.ts';

export { normalize, sniffPicture, type DocxPicture } from './package.ts';
export { THEME } from './theme.ts';

export interface DocxOptions {
  /** The picture of a figure or gallery image, by its src as written in the source; undefined when it cannot be read. */
  picture?: (src: string) => DocxPicture | undefined;
  /** The drawing of a diagram, chart or UI specimen (the caller draws them); undefined falls back to text. */
  drawing?: (block: Block) => DocxPicture | undefined;
  /** Created and modified date in the properties; without it they are left out, so builds are byte-identical. */
  date?: Date;
}

/** The Word language tag for a document language: a region is added where Word needs one for proofing. */
export function wordLang(lang: string): string {
  if (lang.includes('-')) return lang;
  return ({ cs: 'cs-CZ', en: 'en-GB', de: 'de-DE', sk: 'sk-SK' } as Record<string, string>)[lang.toLowerCase()] ?? lang;
}

// A4 with 20 mm margins (twips: 1/1440 inch; 1 CSS px = 15 twips)
const PAGE = { width: 11906, height: 16838, margin: 1134 };
const CONTENT_PX = Math.floor((PAGE.width - 2 * PAGE.margin) / 15);
/** Indent of one list level and of a definition under its term. */
const STEP = 360;

const C = THEME.colors;
const F = THEME.fonts;
const S = THEME.sizes;
const TONES: Record<string, string> = {
  info: C['text-info'], note: C['text-info'], tip: C['text-success'], success: C['text-success'], important: C['text-ai'],
  warning: C['text-warning'], caution: C['text-error'], error: C['text-error'],
  neutral: C['text-secondary'], ai: C['text-ai'], accent: C['text-accent'],
};

/** Where blocks are placed: their indent, the panel around them, the paragraph style. */
interface Frame { indent: number; box?: { color: string; fill?: string }; style?: string }
/** Run formatting collected from the inline tree. */
interface Fmt { bold?: boolean; italics?: boolean; strike?: boolean; mono?: boolean; color?: string; shade?: string; size?: number; superScript?: boolean }

interface Ctx {
  lang: Lang;
  L: Labels;
  d: DocInfo;
  options: DocxOptions;
  footnotes: Record<number, { children: Paragraph[] }>;
  noteDone: Set<string>;
  /** Numbering definitions: one per list kind and start number. */
  numbering: Map<string, ILevelsOptions[]>;
  lists: number;
  bookmarks: Map<string, string>;
  bookmarkNames: Set<string>;
  tableCaptions: string[];
  diagrams: Extract<Block, { type: 'diagram' }>[];
  pictures: number;
  /** Ids that become bookmarks besides the contents entries: glossary terms. */
  anchorIds: Set<string>;
}

type Child = Paragraph | Table;

/** A Word bookmark name for a LibKa id: letters, digits and _, at most 40 characters, unique. */
function bookmark(c: Ctx, id: string): string {
  let name = c.bookmarks.get(id);
  if (name) return name;
  const base = (id.startsWith('lk-') ? id : `lk-${id}`).replace(/[^A-Za-z0-9_]/g, '_').slice(0, 36);
  name = base;
  for (let i = 2; c.bookmarkNames.has(name); i++) name = `${base}_${i}`;
  c.bookmarks.set(id, name);
  c.bookmarkNames.add(name);
  return name;
}

const text = (c: Ctx, s: string, verbatim = false) => (c.lang === 'cs' && !verbatim ? czechText(s) : s);

function run(c: Ctx, value: string, f: Fmt, style?: string): TextRun {
  return new TextRun({
    text: text(c, value, f.mono), ...(style ? { style } : {}),
    ...(f.bold ? { bold: true } : {}), ...(f.italics ? { italics: true } : {}), ...(f.strike ? { strike: true } : {}),
    ...(f.mono ? { font: F.mono, size: S.code } : {}), ...(f.size ? { size: f.size } : {}), ...(f.color ? { color: f.color } : {}),
    ...(f.shade ? { shading: { type: ShadingType.CLEAR, color: 'auto', fill: f.shade } } : {}),
    ...(f.superScript ? { superScript: true } : {}),
  });
}

/** A link: to a bookmark for #id (when the id becomes one), otherwise to the address. */
function link(c: Ctx, href: string, children: TextRun[]): ParagraphChild[] {
  if (!href.startsWith('#')) return [new ExternalHyperlink({ link: href, children })];
  const id = href.slice(1);
  const known = c.d.toc.some((e) => e.id === id) || c.anchorIds.has(id);
  return known ? [new InternalHyperlink({ anchor: bookmark(c, id), children })] : children;
}

function inlines(c: Ctx, nodes: Inline, f: Fmt = {}): ParagraphChild[] {
  return nodes.flatMap((n) => inlineNode(c, n, f));
}

function inlineNode(c: Ctx, n: PhrasingContent, f: Fmt): ParagraphChild[] {
  switch (n.type) {
    case 'text': return [run(c, n.value, f)];
    case 'strong': return inlines(c, n.children, { ...f, bold: true });
    case 'emphasis': return inlines(c, n.children, { ...f, italics: true });
    case 'delete': return inlines(c, n.children, { ...f, strike: true });
    case 'inlineCode': return [run(c, n.value, { ...f, mono: true, shade: C['bg-elevated'] })];
    case 'break': return [new TextRun({ break: 1 })];
    case 'image': return [run(c, n.alt ?? '', f)];
    case 'link': {
      const href = safeHref(n.url);
      return href === null ? inlines(c, n.children, f) : link(c, href, linkRuns(c, n.children, f));
    }
    case 'footnoteReference': return [footnote(c, n.identifier, n.label ?? n.identifier)];
    default: {
      const d = n as unknown as { type: string; name?: string; children?: PhrasingContent[]; attributes?: Record<string, string> };
      if (d.type === 'citation') return citation(c, d as unknown as Citation, f);
      if (d.type === 'textDirective' && d.name === 'kbd') return kbd(c, kbdKeys(plainText(d.children ?? [])), f);
      if (d.type === 'textDirective' && d.name === 'badge') {
        const v = d.attributes?.variant ?? 'neutral';
        return [run(c, plainText(d.children ?? []), { ...f, bold: true, color: TONES[v] ?? TONES.neutral!, shade: C['bg-elevated'] })];
      }
      return [run(c, plainText([n]), f)];
    }
  }
}

/** Link text in the Hyperlink character style (accent color, underlined). */
function linkRuns(c: Ctx, nodes: Inline, f: Fmt): TextRun[] {
  const flat = (list: Inline, g: Fmt): TextRun[] => list.flatMap((n): TextRun[] => n.type === 'text' ? [run(c, n.value, g, 'Hyperlink')]
    : n.type === 'strong' ? flat(n.children, { ...g, bold: true }) : n.type === 'emphasis' ? flat(n.children, { ...g, italics: true })
    : n.type === 'inlineCode' ? [run(c, n.value, { ...g, mono: true }, 'Hyperlink')] : [run(c, plainText([n]), g, 'Hyperlink')]);
  return flat(nodes, f);
}

function kbd(c: Ctx, keys: string[], f: Fmt): ParagraphChild[] {
  return keys.flatMap((k, i) => [...(i ? [run(c, '+', f)] : []), run(c, k, { ...f, mono: true, shade: C['bg-elevated'] })]);
}

/** A note's first use is a Word footnote; a later use repeats its number, as on the web page. */
function footnote(c: Ctx, id: string, label: string): ParagraphChild {
  const n = c.d.notes.get(id);
  if (!n) return run(c, `[^${label}]`, {});
  if (c.noteDone.has(id)) return run(c, String(n), { superScript: true });
  c.noteDone.add(id);
  const note = c.d.footnotes.find((x) => x.id === id)!;
  // Word puts the note's number before its first paragraph; a space keeps it apart from the text
  const [first, ...rest] = note.body;
  const fr: Frame = { indent: 0, style: 'FootnoteText' };
  c.footnotes[n] = { children: [...(first?.type === 'paragraph' ? [para([run(c, ' ', {}), ...inlines(c, first.text)], fr)] : first ? block(c, first, fr) : []),
    ...blocks(c, rest, fr)] as Paragraph[] };
  return new FootnoteReferenceRun(n);
}

function citation(c: Ctx, cite: Citation, f: Fmt): ParagraphChild[] {
  const { open, close, sep, items } = citationParts(cite, c.d, c.L);
  const out: ParagraphChild[] = [run(c, open, f)];
  items.forEach((it, i) => {
    if (i) out.push(run(c, sep, f));
    out.push(it.known && c.d.listRefs ? new InternalHyperlink({ anchor: bookmark(c, `lk-ref-${it.id}`), children: [run(c, it.label, f, 'Hyperlink')] }) : run(c, it.label, f));
    if (it.locator) out.push(run(c, `, ${it.locator}`, f));
  });
  out.push(run(c, close, f));
  return out;
}

/* ---------- paragraphs ---------- */

function boxBorder(color: string): IBordersOptions {
  const side = { style: BorderStyle.SINGLE, size: 6, color: C['border-default'], space: 6 };
  return { top: side, bottom: side, right: side, left: { style: BorderStyle.SINGLE, size: 24, color, space: 8 } };
}

function para(children: ParagraphChild[], fr: Frame, extra: Omit<IParagraphOptions, 'children'> = {}): Paragraph {
  const { indent, ...rest } = extra;
  const left = fr.indent + Number((indent as { left?: number } | undefined)?.left ?? 0);
  return new Paragraph({
    children,
    ...(fr.style && !rest.style && !rest.heading ? { style: fr.style } : {}),
    ...(left || indent ? { indent: { ...(indent as object), left } } : {}),
    ...(fr.box ? { border: boxBorder(fr.box.color), shading: { type: ShadingType.CLEAR, color: 'auto', fill: fr.box.fill ?? C['bg-surface'] } } : {}),
    ...rest,
  });
}

const label = (c: Ctx, value: string, fr: Frame, f: Fmt = {}) => para([run(c, value, { bold: true, ...f })], fr, { keepNext: true });
const caption = (c: Ctx, value: string, fr: Frame, keepNext = false) => para([run(c, value, {})], fr, { style: 'Caption', ...(keepNext ? { keepNext: true } : {}) });

/** Blocks inside list items and panels: the first paragraph may take a prefix (a number is the list's own). */
function blocks(c: Ctx, list: Block[], fr: Frame): Child[] {
  return list.flatMap((b) => block(c, b, fr));
}

/* ---------- lists ---------- */

function levels(kind: 'bullet' | 'ordered', start = 1): ILevelsOptions[] {
  const bullets = ['•', '◦', '▪'];
  return Array.from({ length: 6 }, (_, level) => ({
    level, start: level === 0 ? start : 1,
    format: kind === 'bullet' ? LevelFormat.BULLET : [LevelFormat.DECIMAL, LevelFormat.LOWER_LETTER, LevelFormat.LOWER_ROMAN][level % 3]!,
    text: kind === 'bullet' ? bullets[level % 3]! : `%${level + 1}.`,
    alignment: AlignmentType.LEFT,
    style: { paragraph: { indent: { left: STEP * (level + 1), hanging: STEP } } },
  }));
}

/** A list instance of its own (so its numbering restarts), with its start number. */
function listRef(c: Ctx, ordered: boolean, start = 1): { reference: string; instance: number } {
  const reference = ordered ? `lk-ordered-${start}` : 'lk-bullet';
  if (!c.numbering.has(reference)) c.numbering.set(reference, levels(ordered ? 'ordered' : 'bullet', start));
  return { reference, instance: ++c.lists };
}

/** One list item: its first paragraph carries the number or bullet, the rest is indented under it. */
function item(c: Ctx, first: ParagraphChild[], rest: Block[], ref: { reference: string; instance: number }, level: number, fr: Frame): Child[] {
  const numbered = para(first, fr, { numbering: { ...ref, level }, indent: { left: STEP * (level + 1), hanging: STEP } });
  const under: Frame = { ...fr, indent: fr.indent + STEP * (level + 1) };
  return [numbered, ...rest.flatMap((b) => b.type === 'list' ? list(c, b, fr, level + 1) : block(c, b, under))];
}

function list(c: Ctx, b: Extract<Block, { type: 'list' }>, fr: Frame, level = 0): Child[] {
  const ref = listRef(c, b.ordered, b.start ?? 1);
  return b.items.flatMap((i) => {
    const [head, ...rest] = i;
    return head?.type === 'paragraph' ? item(c, inlines(c, head.text), rest, ref, level, fr) : item(c, [], i, ref, level, fr);
  });
}

/* ---------- tables, pictures, code ---------- */

const cellBorders = { top: { style: BorderStyle.SINGLE, size: 4, color: C['border-strong'] }, bottom: { style: BorderStyle.SINGLE, size: 4, color: C['border-strong'] },
  left: { style: BorderStyle.SINGLE, size: 4, color: C['border-strong'] }, right: { style: BorderStyle.SINGLE, size: 4, color: C['border-strong'] } };

/** A data table: its caption above it and as its alternative text, a header row that repeats on every page. */
function table(c: Ctx, title: string, head: ParagraphChild[][], rows: ParagraphChild[][][], fr: Frame, rowHeaders = false): Child[] {
  c.tableCaptions.push(title);
  const cell = (children: ParagraphChild[], header: boolean) => new TableCell({
    children: [new Paragraph({ children, style: 'LibKaTableText' })],
    borders: cellBorders,
    margins: { top: 60, bottom: 60, left: 100, right: 100 },
    ...(header ? { shading: { type: ShadingType.CLEAR, color: 'auto', fill: C['bg-elevated'] } } : {}),
  });
  return [
    caption(c, title, fr, true),
    new Table({
      width: { size: 100, type: WidthType.PERCENTAGE },
      ...(fr.indent ? { indent: { size: fr.indent, type: WidthType.DXA } } : {}),
      rows: [
        new TableRow({ tableHeader: true, cantSplit: true, children: head.map((h) => headerCell(h)) }),
        ...rows.map((r) => new TableRow({ cantSplit: true, children: r.map((x, i) => (rowHeaders && i === 0 ? headerCell(x, false) : cell(x, false))) })),
      ],
    }),
    para([], { indent: 0 }, { spacing: { after: 0, line: 120 } }),
  ];
  function headerCell(children: ParagraphChild[], shaded = true) {
    return new TableCell({
      children: [new Paragraph({ children, style: 'LibKaTableHeader' })],
      borders: cellBorders,
      margins: { top: 60, bottom: 60, left: 100, right: 100 },
      ...(shaded ? { shading: { type: ShadingType.CLEAR, color: 'auto', fill: C['bg-elevated'] } } : {}),
    });
  }
}

/** A picture scaled to fit the text width, with its alternative text. */
function picture(c: Ctx, p: DocxPicture, alt: { title: string; description: string }, fr: Frame): Paragraph {
  const max = CONTENT_PX - Math.ceil(fr.indent / 15);
  const scale = Math.min(1, max / p.width);
  return para([new ImageRun({
    type: p.type, data: p.data, transformation: { width: Math.round(p.width * scale), height: Math.round(p.height * scale) },
    altText: { name: `${c.L.picture} ${++c.pictures}`, title: alt.title, description: alt.description },
  })], fr, { keepNext: true, spacing: { after: 60 } });
}

function code(c: Ctx, b: { lang: string | null; value: string; title?: string; marked?: number[] }, fr: Frame): Child[] {
  const marked = new Set(b.marked ?? []);
  const lines = b.value.split('\n');
  const box: Frame = { ...fr, box: { color: C['border-strong'], fill: C['bg-elevated'] } };
  return [
    ...(b.title ? [caption(c, b.title, fr, true)] : []),
    ...lines.map((l, i) => para([run(c, l || ' ', { mono: true, ...(marked.has(i + 1) ? { bold: true, color: C['text-primary'] } : {}) })], box,
      { style: 'LibKaCode', ...(i < lines.length - 1 ? { keepNext: true } : {}) })),
  ];
}

/* ---------- blocks ---------- */

function block(c: Ctx, b: Block, fr: Frame): Child[] {
  const L = c.L;
  switch (b.type) {
    case 'heading': {
      const heading = b.level === 2 ? HeadingLevel.HEADING_1 : b.level === 3 ? HeadingLevel.HEADING_2 : HeadingLevel.HEADING_3;
      return [new Paragraph({ heading, children: [new Bookmark({ id: bookmark(c, b.id), children: inlines(c, b.text) as TextRun[] })] })];
    }
    case 'paragraph':
      return [para(inlines(c, b.text), fr)];
    case 'list':
      return list(c, b, fr);
    case 'code':
      return code(c, b, fr);
    case 'callout': {
      const tone = L.tone[b.variant];
      const title = b.title && b.title.toLowerCase() !== tone.toLowerCase() ? `${tone}: ${b.title}` : (b.title ?? tone);
      const box: Frame = { ...fr, box: { color: TONES[b.variant]!, fill: C['bg-elevated'] } };
      return [label(c, title, box, { color: TONES[b.variant]! }), ...blocks(c, b.body, box)];
    }
    case 'summary': {
      const box: Frame = { ...fr, box: { color: C['text-accent'], fill: C['bg-elevated'] } };
      const ref = listRef(c, false);
      return [label(c, b.title ?? L.keyTakeaways, box),
        ...b.items.flatMap((i) => item(c, inlines(c, i), [], ref, 0, box)),
        ...(b.source === 'ai' ? [para([run(c, L.aiAssisted, { bold: true, color: TONES.ai!, shade: C['bg-elevated'] }), run(c, ` ${fill(L.reviewedBy, { name: b.reviewedBy ?? '' })}`, {})], box)] : [])];
    }
    case 'toc':
      return contents(c, b.title ?? L.contents, c.d.toc.filter((e) => e.level <= b.depth), fr);
    case 'diagram': {
      c.diagrams.push(b);
      const p = c.options.drawing?.(b);
      return [p ? picture(c, p, { title: b.title, description: b.desc }, fr) : para([run(c, b.desc, {})], fr, { keepNext: true }), caption(c, b.title, fr)];
    }
    case 'code-group':
      return b.items.flatMap(({ title, ...rest }) => [...(title ? [label(c, title, fr)] : []), ...code(c, rest, fr)]);
    case 'timeline': {
      const at = b.current ? b.items.findIndex((i) => i.when === b.current) : -1;
      return [...(b.caption ? [caption(c, b.caption, fr, true)] : []),
        ...b.items.flatMap((it, i) => [label(c, i === at ? `${it.when} · ${L.now}` : it.when, fr), ...blocks(c, it.body, { ...fr, indent: fr.indent + STEP })])];
    }
    case 'comparison': {
      const head = b.head.map((h, i) => [...inlines(c, h), ...(b.highlight === i && i > 0 ? [run(c, ` (${b.badge ?? L.recommended})`, {})] : [])]);
      const rows = b.rows.map((r) => r.map((cell) => cell.mark
        ? [run(c, L.mark[cell.mark], {}), ...(cell.text.length ? [run(c, ' (', {}), ...inlines(c, cell.text), run(c, ')', {})] : [])]
        : inlines(c, cell.text)));
      return table(c, b.caption, head, rows, fr, true);
    }
    case 'release':
      return [new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new Bookmark({ id: bookmark(c, b.id), children: [run(c, b.version, {})] })] }),
        ...(b.date ? [para([run(c, `${L.released}: ${b.date}`, {})], fr, { style: 'LibKaMeta' })] : []),
        ...blocks(c, b.intro ?? [], fr),
        ...b.groups.flatMap((g) => [label(c, L.release[g.kind], fr), ...blocks(c, g.body, fr)])];
    case 'references':
      return references(c, b.title ?? L.references);
    case 'doc-status': {
      const box: Frame = { ...fr, box: { color: C['border-strong'], fill: C['bg-elevated'] } };
      return [label(c, L.docStatus, box), ...statusLines(b, L).map(([k, v]) => para([run(c, `${k}: `, { bold: true }), run(c, v, {})], box))];
    }
    case 'section':
      // a part is a Heading 1 like the sections it groups, larger and in the accent color, on a new page when asked
      return [new Paragraph({ heading: HeadingLevel.HEADING_1, ...(b.break === 'page' ? { pageBreakBefore: true } : {}),
        children: [new Bookmark({ id: bookmark(c, b.id), children: [run(c, b.title, { size: S.title - 12, color: C['text-accent'] })] })] }), ...blocks(c, b.body, fr)];
    case 'dl':
      return [...(b.caption ? [caption(c, b.caption, fr, true)] : []),
        ...b.items.flatMap((i) => [label(c, i.term, fr), ...blocks(c, i.body, { ...fr, indent: fr.indent + STEP })])];
    case 'cta': {
      const href = safeHref(b.href);
      const url = /^(https?|mailto):/i.test(b.href) ? b.href.replace(/^mailto:/i, '') : '';
      const action = [run(c, b.label, { bold: true }, href === null ? undefined : 'Hyperlink')];
      return [...(b.text ? [para(inlines(c, b.text), fr, { keepNext: true })] : []),
        para([...(href === null ? action : link(c, href, action)), ...(url ? [run(c, ` (${url})`, {})] : [])], fr)];
    }
    case 'steps': {
      const ref = listRef(c, true, b.start ?? 1);
      return b.steps.flatMap((s) => item(c, inlines(c, s.title, { bold: true }), s.body, ref, 0, fr));
    }
    case 'checklist':
      return b.items.map((i) => para([run(c, `${i.done ? '☑' : '☐'} ${i.done ? L.done : L.open}`, { bold: true }), ...inlines(c, i.text)], fr, { indent: { left: STEP, hanging: STEP } }));
    case 'table':
      return table(c, b.caption, b.head.map((h) => inlines(c, h)), b.rows.map((r) => r.map((x) => inlines(c, x))), fr);
    case 'figure': {
      const p = safeHref(b.src) === null ? undefined : c.options.picture?.(b.src);
      return [p ? picture(c, p, { title: b.caption, description: b.alt }, fr) : para([run(c, `[ ${b.alt} ]`, {})], fr, { keepNext: true }), caption(c, b.caption, fr)];
    }
    case 'notes':
      return [];   // speaker notes belong to the deck only
    case 'tabs':
      return b.tabs.flatMap((t) => [label(c, t.label, fr), ...blocks(c, t.body, fr)]);
    case 'accordion':
      return b.items.flatMap((i) => [label(c, i.title, fr), ...blocks(c, i.body, fr)]);
    case 'shortcuts':
      return table(c, b.caption, [[run(c, L.keys, {})], [run(c, L.action, {})]], b.items.map((i) => [kbd(c, i.keys, {}), inlines(c, i.text)]), fr);
    case 'glossary':
      return b.items.flatMap((i) => {
        c.anchorIds.add(i.id);
        return [para([new Bookmark({ id: bookmark(c, i.id), children: [run(c, i.term, { bold: true })] })], fr, { keepNext: true }),
          ...blocks(c, i.body, { ...fr, indent: fr.indent + STEP })];
      });
    case 'compare':
      return b.items.flatMap((i) => {
        const color = i.kind === 'do' ? C['text-success'] : C['text-error'];
        const box: Frame = { ...fr, box: { color, fill: C['bg-elevated'] } };
        return [label(c, `${i.kind === 'do' ? '✓' : '✗'} ${i.kind === 'do' ? L.do : L.dont}`, box, { color }), label(c, i.title, box), ...blocks(c, i.body, box)];
      });
    case 'quote': {
      const cite = b.cite ? safeHref(b.cite) : null;
      const inner = blocks(c, b.body, { ...fr, style: 'Quote' });
      if (!b.source) return inner;
      const source = [run(c, b.source, { italics: true }, cite ? 'Hyperlink' : undefined)];
      return [...inner, para([run(c, '— ', {}), ...(cite ? link(c, cite, source) : source)], { ...fr, style: 'Quote' })];
    }
    case 'cards':
      return b.cards.flatMap((card) => {
        const box: Frame = { ...fr, box: { color: C['border-strong'] } };
        const href = card.href ? safeHref(card.href) : null;
        const title = [run(c, card.title, { bold: true }, href ? 'Hyperlink' : undefined)];
        return [...(card.badge ? [label(c, card.badge, box, { color: C['text-accent'], size: S.small })] : []),
          para(href ? link(c, href, title) : title, box, { keepNext: true }), ...blocks(c, card.body, box)];
      });
    case 'statement':
      return [para(inlines(c, b.text), fr, { style: 'LibKaStatement' })];
    case 'metrics':
      return b.items.map((i) => para([run(c, i.value, { bold: true, size: S.h2 }), new TextRun({ break: 1 }), ...inlines(c, i.label)], fr, { keepLines: true }));
    case 'gallery':
      return b.images.flatMap((i) => block(c, { type: 'figure', ...i }, fr));
    case 'video': {
      const href = safeHref(b.src);
      const [before, after] = L.videoAt.split('{src}') as [string, string?];
      const src = [run(c, b.src, {}, href ? 'Hyperlink' : undefined)];
      return [para([run(c, fill(before, { title: b.title }), {}), ...(href ? link(c, href, src) : src), ...(after ? [run(c, after, {})] : [])], fr, { keepNext: true }),
        label(c, L.transcript, fr), ...blocks(c, b.transcript, fr)];
    }
    case 'chart': {
      const { fmt, summary } = chartText(b, c.lang, L);
      const p = c.options.drawing?.(b);
      return [p ? picture(c, p, { title: b.caption, description: summary }, fr) : para([run(c, summary, {})], fr, { keepNext: true }),
        caption(c, b.caption, fr),
        ...table(c, `${b.caption} (${L.data})`, [[run(c, b.category, {})], ...b.series.map((s) => [run(c, s.name, {})])],
          b.labels.map((l, i) => [[run(c, l, {})], ...b.series.map((s) => [run(c, fmt(s.values[i] ?? 0), {})])]), fr, true)];
    }
    case 'ui': {
      const desc = describeUi(b, c.lang);
      const p = c.options.drawing?.(b);
      return [p ? picture(c, p, { title: b.caption, description: desc }, fr) : para([run(c, desc, {})], fr, { keepNext: true }), caption(c, b.caption, fr)];
    }
  }
}

function statusLines(s: { status?: string | undefined; owner?: string | undefined; reviewed?: string | undefined; nextReview?: string | undefined }, L: Labels): [string, string][] {
  return ([[L.status, s.status], [L.owner, s.owner], [L.reviewed, s.reviewed], [L.nextReview, s.nextReview]] as [string, string | undefined][])
    .filter((x): x is [string, string] => Boolean(x[1]));
}

/** Contents: links to the headings' bookmarks, parts in bold, ### indented. */
function contents(c: Ctx, title: string, entries: DocInfo['toc'], fr: Frame): Child[] {
  const list = entries.filter((e) => e.id !== NOTES_ID);   // notes are Word footnotes, not a section
  if (!list.length) return [];
  return [label(c, title, fr, { color: C['text-secondary'] }),
    ...list.map((e) => para([new InternalHyperlink({ anchor: bookmark(c, e.id), children: [run(c, e.text, e.part ? { bold: true } : {}, 'Hyperlink')] })],
      fr, { style: e.level === 3 ? 'TOC2' : 'TOC1' }))];
}

function references(c: Ctx, title: string): Child[] {
  if (!c.d.listRefs) return [];
  const refs = orderedReferences(c.d, c.lang);
  const ref = c.d.style === 'numeric' ? listRef(c, true) : null;
  const entry = (r: (typeof refs)[number]) => [new Bookmark({ id: bookmark(c, `lk-ref-${r.id}`), children: [] as TextRun[] }),
    ...referenceParts(r, c.L).map((p): ParagraphChild => p.kind === 'title' ? run(c, p.text, { italics: true })
      : p.kind === 'link' ? new ExternalHyperlink({ link: p.href!, children: [run(c, p.text, {}, 'Hyperlink')] }) : run(c, p.text, {}))];
  return [new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new Bookmark({ id: bookmark(c, REFERENCES_ID), children: [run(c, title, {})] })] }),
    ...refs.map((r) => (ref ? para(entry(r), { indent: 0 }, { numbering: { ...ref, level: 0 }, indent: { left: STEP, hanging: STEP } })
      : para(entry(r), { indent: 0 }, { indent: { left: STEP, hanging: STEP } })))];
}

/* ---------- the document ---------- */

function styles(lang: string) {
  const line = Math.round(240 * THEME.lineHeight);
  const color = C['text-primary'];
  const family = (f: 'brand' | 'ui') => F[f];
  return {
    default: {
      document: { run: { font: F.ui, size: S.body, color, language: { value: lang } }, paragraph: { spacing: { after: 160, line } } },
      title: { run: { font: family(THEME.families.title), size: S.title, bold: true, color }, paragraph: { spacing: { after: 120, line: 240 } } },
      heading1: { run: { font: family(THEME.families.h2), size: S.h2, bold: true, color }, paragraph: { spacing: { before: 360, after: 120, line: 276 }, keepNext: true, keepLines: true, outlineLevel: 0 } },
      heading2: { run: { font: family(THEME.families.h3), size: S.h3, bold: true, color }, paragraph: { spacing: { before: 280, after: 100, line: 276 }, keepNext: true, keepLines: true, outlineLevel: 1 } },
      heading3: { run: { font: family(THEME.families.h3), size: S.h4, bold: true, color }, paragraph: { spacing: { before: 240, after: 80, line: 276 }, keepNext: true, keepLines: true, outlineLevel: 2 } },
      hyperlink: { run: { color: C['text-accent'], underline: {} } },
    },
    paragraphStyles: [
      { id: 'Subtitle', name: 'Subtitle', basedOn: 'Normal', next: 'Normal', quickFormat: true, run: { size: S.subtitle, color: C['text-secondary'] }, paragraph: { spacing: { after: 160 } } },
      { id: 'Caption', name: 'Caption', basedOn: 'Normal', next: 'Normal', quickFormat: true, run: { size: S.small, color: C['text-secondary'], italics: true }, paragraph: { spacing: { before: 60, after: 200, line: 276 } } },
      { id: 'Quote', name: 'Quote', basedOn: 'Normal', next: 'Normal', quickFormat: true, run: { italics: true, color: C['text-primary'] },
        paragraph: { indent: { left: STEP * 2 }, border: { left: { style: BorderStyle.SINGLE, size: 18, color: C['border-strong'], space: 10 } } } },
      { id: 'LibKaMeta', name: 'LibKa Meta', basedOn: 'Normal', next: 'Normal', run: { size: S.small, color: C['text-secondary'] } },
      { id: 'LibKaCode', name: 'LibKa Code', basedOn: 'Normal', next: 'Normal', run: { font: F.mono, size: S.code }, paragraph: { spacing: { after: 0, line: 252 } } },
      { id: 'LibKaStatement', name: 'LibKa Statement', basedOn: 'Normal', next: 'Normal', run: { font: F.brand, size: S.h3, color }, paragraph: { spacing: { before: 200, after: 200, line: 300 } } },
      { id: 'LibKaTableText', name: 'LibKa Table Text', basedOn: 'Normal', run: { size: S.small }, paragraph: { spacing: { after: 0, line: 264 } } },
      { id: 'LibKaTableHeader', name: 'LibKa Table Header', basedOn: 'LibKaTableText', run: { bold: true } },
      { id: 'TOC1', name: 'toc 1', basedOn: 'Normal', next: 'Normal', paragraph: { spacing: { after: 60 } } },
      { id: 'TOC2', name: 'toc 2', basedOn: 'Normal', next: 'Normal', paragraph: { indent: { left: STEP }, spacing: { after: 60 } } },
    ],
  };
}

/** Renders the document as a Word file. */
export async function renderDocx(doc: LibkaDocument, options: DocxOptions = {}): Promise<Uint8Array> {
  const lang = langOf(doc.meta.lang);
  const L = LABELS[lang];
  const tag = wordLang(doc.meta.lang);
  const c: Ctx = {
    lang, L, d: docInfo(doc, L), options, footnotes: {}, noteDone: new Set(), numbering: new Map(), lists: 0,
    bookmarks: new Map(), bookmarkNames: new Set(), tableCaptions: [], diagrams: [], pictures: 0, anchorIds: new Set(),
  };
  for (const b of doc.blocks) if (b.type === 'glossary') b.items.forEach((i) => c.anchorIds.add(i.id));
  const { meta } = doc;
  const fr: Frame = { indent: 0 };
  const panel = doc.blocks.some((b) => b.type === 'doc-status');
  const metaLine = [
    ...([[L.version, meta.version], [L.date, meta.date]] as [string, string | undefined][]).filter((x): x is [string, string] => Boolean(x[1])),
    ...statusLines(meta, L).filter(([k]) => !panel || k === L.status),
  ].map(([k, v]) => `${k}: ${v}`).join(' · ');
  const head: Child[] = [
    new Paragraph({ style: 'Title', children: [run(c, meta.title, {})] }),
    ...(meta.subtitle ? [new Paragraph({ style: 'Subtitle', children: [run(c, meta.subtitle, {})] })] : []),
    ...(metaLine ? [para([run(c, metaLine, {})], fr, { style: 'LibKaMeta' })] : []),
    ...(isDeprecated(meta.status) ? (() => {
      const box: Frame = { indent: 0, box: { color: C['text-error'], fill: C['bg-elevated'] } };
      return [label(c, L.deprecated, box, { color: C['text-error'] }), para([run(c, L.deprecatedText, {})], box)];
    })() : []),
  ];
  // the automatic contents: parts and ## sections, unless a :::toc places them
  const auto = c.d.placedToc ? [] : c.d.toc.filter((e) => e.level === 2 && e.id !== NOTES_ID);
  const body = [...(auto.length >= 2 ? contents(c, L.contents, auto, fr) : []), ...blocks(c, doc.blocks, fr)];
  if (!c.d.placedRefs) body.push(...references(c, L.references));
  if (c.diagrams.length) {
    body.push(new Paragraph({ heading: HeadingLevel.HEADING_1, children: [run(c, L.diagramSources, {})] }),
      ...c.diagrams.flatMap((d) => [label(c, d.title, fr), ...code(c, { lang: 'mermaid', value: d.source }, fr)]));
  }

  const [before, after] = L.page.split('{n}') as [string, string?];
  const document = new Document({
    title: meta.title, ...(meta.subtitle ? { subject: meta.subtitle } : {}), creator: meta.owner ?? 'LibKa', lastModifiedBy: 'LibKa',
    description: L.builtWith, revision: 1,
    styles: styles(tag),
    theme: { fonts: { headings: F.brand, body: F.ui } },
    numbering: { config: [...c.numbering].map(([reference, lv]) => ({ reference, levels: lv })) },
    footnotes: c.footnotes,
    sections: [{
      properties: { page: { size: { width: PAGE.width, height: PAGE.height }, margin: { top: PAGE.margin, bottom: PAGE.margin, left: PAGE.margin, right: PAGE.margin } } },
      footers: { default: new Footer({ children: [new Paragraph({ style: 'LibKaMeta', alignment: AlignmentType.CENTER,
        children: [new TextRun({ font: F.ui, children: [before, PageNumber.CURRENT, ...(after ? [after] : [])] })] })] }) },
      children: [...head, ...body],
    }],
  });
  const packed = new Uint8Array(await Packer.toArrayBuffer(document));
  return normalize(packed, { lang: tag, tableCaptions: c.tableCaptions, ...(options.date ? { date: options.date } : {}) });
}
